def test_known_selection():
    terms = [("income", -1.20), ("debt-to-income", 0.95), ("missed payments", 0.70)]
    got = solution.applicant_reasons(terms, {"debt-to-income", "missed payments"}, 2)
    assert got == ["debt-to-income", "missed payments"]

def test_fewer_actionable_than_k():
    terms = [("income", -0.35), ("account age", 0.00), ("missed payments", 0.70)]
    assert solution.applicant_reasons(terms, {"missed payments"}, 3) == ["missed payments"]

def test_nothing_actionable():
    terms = [("income", -0.35), ("account age", 0.12)]
    assert solution.applicant_reasons(terms, {"missed payments"}, 2) == []

def test_ranked_by_magnitude():
    terms = [("a", 0.20), ("b", -0.90), ("c", 0.55)]
    assert solution.applicant_reasons(terms, {"a", "b", "c"}, 2) == ["b", "c"]

def test_k_below_one_raises():
    try:
        solution.applicant_reasons([("a", 1.0)], {"a"}, 0)
    except ValueError:
        return
    raise AssertionError("expected ValueError")

def test_ties_keep_input_order():
    terms = [("x", 0.5), ("y", -0.5)]
    assert solution.applicant_reasons(terms, {"x", "y"}, 2) == ["x", "y"]

def test_does_not_mutate():
    terms = [("a", 0.2), ("b", 0.9)]
    solution.applicant_reasons(terms, {"a", "b"}, 1)
    assert terms == [("a", 0.2), ("b", 0.9)]
